'use strict';
const $=s=>document.querySelector(s);
const testingPreview=new URLSearchParams(location.search).has('preview-test');
const storageKey=testingPreview?'reground-v2-qa':'reground-v2';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',project:'<path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M5 7v8a4 4 0 0 0 4 4h8M9 5h7a3 3 0 0 1 0 6H8"/>',check:'<path d="m8 12 3 3 5-6M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/>',layers:'<path d="m3 7 9-4 9 4-9 4zM3 12l9 4 9-4M3 17l9 4 9-4"/>',truck:'<path d="M2 5h12v12H2zM14 10h4l4 4v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',leaf:'<path d="M20 3C8 2 2 7 5 15c5 7 16 2 15-12ZM4 21 16 8"/>',chart:'<path d="M4 3v17h17M8 15v-4M13 15V7M18 15V4"/>',pin:'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 13h8M8 17h5"/>',money:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9M12 6v12"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17v1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',building:'<path d="M5 21V3h14v18M2 21h20M9 7h1M14 7h1M9 11h1M14 11h1M10 21v-5h4v5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v).toLocaleString('en-NZ',{maximumFractionDigits:1});
const money=v=>'$'+Math.round(v).toLocaleString('en-NZ');
const stamp=()=>new Date().toLocaleString('en-NZ',{timeZone:'Pacific/Auckland',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const requirements=['Particle-size distribution','Moisture range','Contamination evidence','Geotechnical suitability','Receiving window & capacity','Receiver conditional acceptance'];
const owners=['Geotechnical consultant · fines / sand / gravel','Field QA lead · 10–18% moisture','Environmental consultant · laboratory review','Project engineer · intended-use assessment','Receiver site manager · 14–28 Oct 2026','Receiver site manager · signed conditions'];
const routes=[{id:'local',label:'Local reuse',name:'Warkworth North',subtitle:'Infrastructure earthworks · engineered fill',distance:8,rate:25,capacity:1600,window:'14–28 Oct 2026',icon:'leaf',tone:'',x:61,y:39},{id:'alternative',label:'Alternative reuse',name:'Mahurangi Landscape',subtitle:'Landscape processor · bulk earthworks',distance:17,rate:31,capacity:1400,window:'14–28 Oct 2026',icon:'layers',tone:'amber',x:79,y:68},{id:'fallback',label:'Fallback disposal',name:'Regional Fill Facility',subtitle:'Disposal contingency · independent acceptance',distance:70,rate:56.45,capacity:5000,window:'14–31 Oct 2026',icon:'truck',tone:'grey',x:28,y:76}];
const seedProject=()=>({id:'RG-024',name:'Warkworth Development',location:'Warkworth, Auckland',material:'Sandy clay',excavated:1800,retained:560,density:1.7,start:'2026-10-14',end:'2026-10-28',route:'local',evidence:{local:[true,true,true,true,true,false],alternative:[true,false,true,false,true,false],fallback:[true,true,true,true,true,true]},files:{},batches:[{id:'B-0217',mass:18.4,moisture:14,fines:42,result:'PASS',reason:'Within agreed receiver envelope',route:'local',delivery:'Delivered',time:'Demo · 09:42'},{id:'B-0218',mass:19.2,moisture:22,fines:44,result:'HOLD',reason:'Moisture outside receiver range; retest required',route:'local',delivery:'Blocked',time:'Demo · 09:48'},{id:'B-0219',mass:17.8,moisture:15,fines:41,result:'PASS',reason:'Within agreed receiver envelope',route:'local',delivery:'In transit',time:'Demo · 09:56'}],log:[]});
let state={version:1,role:'Supplier',org:'Northland Civil',onboarded:false,projectId:'RG-024',projects:[seedProject()],requests:[]};
try{const stored=JSON.parse(localStorage.getItem('reground-v1'));if(!testingPreview&&stored?.version===1&&Array.isArray(stored.projects)&&stored.projects.length)state=stored;}catch{}
let page='dashboard',routeFocus='local',batchResult=null,searchState={material:'Any material',radius:30,quantity:300,start:'2026-10-18',end:'2026-10-22'},modalRole=state.role;
const project=()=>state.projects.find(p=>p.id===state.projectId)||state.projects[0];
const volume=()=>Math.max(0,project().excavated-project().retained);
const selectedRoute=()=>routes.find(r=>r.id===project().route);
const complete=id=>project().evidence[id].filter(Boolean).length;
const readiness=id=>Math.round(complete(id)/6*100);
const accepted=id=>complete(id)===6;
const cost=r=>volume()*r.rate;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Storage unavailable. Keep this tab open to retain changes.');}}
function log(message){project().log.unshift({message,time:stamp()});project().log=project().log.slice(0,30);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
const pill=(text,tone='')=>`<span class="pill ${tone}">${text}</span>`;
const status=s=>pill(s,s==='FAIL'?'red':s==='HOLD'?'amber':'');
const button=(text,action,style='',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
const nav=[['dashboard','grid','Overview'],['forecast','project','Projects & forecast'],['routes','route','Route comparison'],['evidence','check','Acceptance & evidence'],['material','layers','Material profile'],['verification','check','Field verification'],['deliveries','truck','Deliveries'],['impact','chart','Impact & reporting']];
function heading(kicker,title,description,actions=''){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${actions}</div>`;}
function metric(label,value,unit,foot,ic,neutral=false){return `<div class="metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value} <small>${unit}</small></div><div class="metric-foot ${neutral?'neutral':''}">${foot}</div></div>`;}
function legacyRender(){const p=project();$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brandmark">»</span>ReGround</div><div class="brand-sub">BETTER ROUTES. BETTER GROUND.</div><div class="org"><span class="org-icon">${icon('building')}</span><div><b>${esc(state.org)}</b><small>Organisation workspace</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='evidence'?'<span class="count">'+(6-complete(p.route))+'</span>':''}</button>`).join('')}${state.role==='Receiver'?`<button data-page="sources" class="${page==='sources'?'active':''}">${icon('search')}Find material</button>`:''}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<strong>Good ground. Less travel.</strong><span>Plan locally. Verify on site.<br>Keep your project moving.</span></div><button class="user-btn" data-action="onboarding"><span class="avatar">${esc(state.org.slice(0,2).toUpperCase())}</span><span>${esc(state.role)} workspace<small>Change role & organisation</small></span></button></div></aside><div class="shell"><header class="topbar"><div class="crumb"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${nav.find(n=>n[0]===page)?.[2]||'Find material'}</strong></div><div class="top-actions">${pill('Demo workspace','grey')}<select class="project-select" id="project-select" aria-label="Active project">${state.projects.map(x=>`<option value="${esc(x.id)}" ${p.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select class="role-switch" id="role-switch" aria-label="Workspace role"><option ${state.role==='Supplier'?'selected':''}>Supplier</option><option ${state.role==='Receiver'?'selected':''}>Receiver</option></select></div></header><main id="main" class="main" tabindex="-1">${renderPage()}<footer class="footer-note"><span>REGROUND · PLANNING → ACCEPTANCE → VERIFICATION → DELIVERY</span><span>Illustrative Auckland scenario · NZD excl. GST · Saved on this device</span></footer></main></div>`;}
function legacyRenderPage(){return ({dashboard:dashboard,forecast:forecast,routes:routePage,evidence:evidencePage,material:materialPage,verification:verificationPage,deliveries:deliveriesPage,impact:impactPage,sources:sourcesPage}[page]||dashboard)();}
function mapView(){return `<div class="map" aria-label="Illustrative nearby route schematic, not a navigation map"><svg class="cartography" viewBox="0 0 560 300" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="grid" width="36" height="36" patternUnits="userSpaceOnUse" patternTransform="rotate(-15)"><path d="M36 0H0V36" fill="none" stroke="#dfe5d7" stroke-width="1"/></pattern></defs><rect width="560" height="300" fill="url(#grid)"/><path d="M510 0Q440 60 475 105T460 200T530 300H560V0Z" fill="#d4e4df"/><path d="M0 90Q90 125 170 90T340 70T520 140M60 0Q150 60 185 155T240 300M0 240Q160 160 300 180T490 260" fill="none" stroke="#fff" stroke-width="10"/><path d="M150 300Q240 220 225 150T280 0" fill="none" stroke="#dad3b9" stroke-width="8"/><path d="M150 300Q240 220 225 150T280 0" fill="none" stroke="#fff9e8" stroke-width="4"/><path d="M224 150Q280 132 341 117" fill="none" stroke="#416747" stroke-width="3" stroke-dasharray="6 4"/><path d="M224 150Q330 205 442 204" fill="none" stroke="#b27a58" stroke-width="2.5" stroke-dasharray="5 5"/><path d="M224 150Q187 202 157 228" fill="none" stroke="#8e9687" stroke-width="2.5" stroke-dasharray="5 5"/></svg><span class="map-title">AUCKLAND REGION</span><span class="map-place" style="left:35%;top:64%">WARKWORTH</span><span class="map-place" style="left:69%;top:26%">MAHURANGI</span><span class="map-place" style="left:83%;top:43%">COAST</span><span class="map-pin origin" style="left:40%;top:50%" title="Source project">S</span>${routes.map((r,i)=>`<button class="map-pin ${routeFocus===r.id?'active':''}" style="left:${r.x}%;top:${r.y}%" data-action="focus-route" data-id="${r.id}" aria-label="Show ${r.name}">${i+1}</button>`).join('')}<span class="map-label">Illustrative route schematic · not to scale</span><div class="map-float">${routes.find(r=>r.id===routeFocus).distance} km · ${routes.find(r=>r.id===routeFocus).label}</div></div><div class="legend"><span><i></i>Local reuse</span><span><i class="clay"></i>Alternative reuse</span><span><i class="grey"></i>Fallback disposal</span></div>`;}
function legacyDashboard(){const p=project(),r=selectedRoute(),ready=readiness(r.id),saving=cost(routes[2])-cost(r);return heading('PROJECT CONTROL',state.role==='Receiver'?'Your next source, planned.':'Your ground. A clearer path.',state.role==='Receiver'?'Review source evidence and prepare your receiving window.':'A little planning above ground. A lot less uncertainty below.',button(icon('plus')+' New project','new-project','primary'))+`<section class="hero"><div><div class="eyebrow" style="margin-bottom:8px">PLAN FIRST. MOVE WITH CONFIDENCE.</div><h2>Know the route before you dig.</h2><p>Reduce soil-management cost without adding programme risk.</p></div><div class="mini"><div class="eyebrow">YOUR NEXT MILESTONE</div><strong>${accepted(r.id)?'Field verification':'Conditional acceptance'}</strong><small>${accepted(r.id)?'Verify every batch before dispatch':'Complete receiver sign-off before haulage'}</small></div></section><section class="metrics">${metric('Forecast surplus',num(volume()),'t','Planning estimate · editable','layers')}${metric('Potential cost saving',money(saving),'','vs. fallback disposal estimate','money')}${metric('Acceptance readiness',ready,'%',complete(r.id)+' of 6 requirements complete','check')}${metric('Planned haul distance',r.distance,'km','One-way route estimate','route',true)}</section><div class="grid-main"><section class="panel"><div class="section-title"><h2>Active project</h2><button class="text-btn" data-page="forecast">View project</button></div><div class="project-head"><div><div class="eyebrow">${esc(p.id)} · EARTHWORKS</div><h3>${esc(p.name)}</h3><div class="sub">${icon('pin')} ${esc(p.location)}</div></div>${pill(accepted(r.id)?'Conditionally accepted':'Planning stage',accepted(r.id)?'':'amber')}</div><div class="project-stats"><div><span>Material</span><strong>${esc(p.material)}</strong></div><div><span>Expected surplus</span><strong>${num(volume())} tonnes</strong></div><div><span>Excavation window</span><strong>${shortDate(p.start)} – ${shortDate(p.end)}</strong></div></div><div class="stepper">${['Forecast','Find routes','Acceptance','Verify','Deliver'].map((s,i)=>`<div class="step ${i<(accepted(r.id)?3:2)?'done':i===(accepted(r.id)?3:2)?'current':''}"><div class="circle">${i<(accepted(r.id)?3:2)?'✓':i+1}</div>${s}</div>`).join('')}</div><div class="callout">${icon(accepted(r.id)?'check':'alert')}<div><strong>${accepted(r.id)?'Route conditions recorded':'Your next action'}</strong><br>${accepted(r.id)?'Check batch conformance before dispatch.':(6-complete(r.id))+' requirement(s) need attention for '+r.name+'.'}</div><button class="text-btn" data-page="${accepted(r.id)?'verification':'evidence'}">${accepted(r.id)?'Verify batch':'Review evidence'}</button></div><div class="route-mini"><span class="route-line">${icon('route')}</span><div><strong>${r.name}</strong><div class="sub">${r.label} · ${r.distance} km from source</div></div><div class="right"><strong>${money(cost(r))}</strong><div class="sub">Estimated all-in cost</div></div></div></section><section class="panel"><div class="section-title"><h2>Routes within reach</h2><button class="text-btn" data-page="routes">Compare routes</button></div>${mapView()}<div class="route-list">${routes.slice(0,2).map((x,i)=>`<button class="nearby-row ${routeFocus===x.id?'selected':''}" data-action="focus-route" data-id="${x.id}"><span><b>${i+1}. ${x.name}</b><small>${x.label} · ${num(x.capacity)} t capacity</small></span><b>${x.distance} km</b></button>`).join('')}</div></section></div><div class="lower-grid"><section class="panel"><div class="section-title"><h2>Latest field batches</h2><button class="text-btn" data-page="verification">Open field verification</button></div>${batchTable(p.batches.slice(-3).reverse(),false)}</section><section class="panel"><div class="section-title"><h2>Project activity</h2>${pill('Local records','grey')}</div>${activity()}</section></div>${state.role==='Receiver'?`<section class="panel mt export-box"><div><h2 style="margin:0 0 6px;font-size:20px">Find a source that fits your site</h2><div class="sub">Filter forecast material by volume, distance and receiving window.</div></div>${button('Find material','find-sources','primary')}</section>`:''}`;}
function shortDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'short'});}
function activity(){const list=project().log.length?project().log.slice(0,3):[{message:'Material characterisation added to project',time:'Demo activity · Planning'},{message:'Local reuse route shortlisted',time:'Demo activity · Route review'},{message:'Receiver sign-off awaiting review',time:'Demo activity · Acceptance'}];return list.map((l,i)=>`<div class="activity"><span class="activity-icon">${i===0?'✓':i===1?'↗':'◷'}</span><div><p>${esc(l.message)}</p><small>${esc(l.time)}</small></div></div>`).join('');}
function batchTable(batches,actions=true){if(!batches.length)return '<div class="empty">No batches yet. Record your first field check.</div>';return `<div class="table-wrap"><table><thead><tr><th>Batch ID</th><th>Weight</th><th>QA status</th><th>${actions?'Route / action':'Delivery'}</th></tr></thead><tbody>${batches.map(b=>`<tr><td class="batch-id">${esc(b.id)}<div class="sub" style="font-size:11px;font-weight:400">${esc(b.time)}</div></td><td>${num(b.mass)} t</td><td>${status(b.result)}</td><td>${actions?`<div class="sub">${routes.find(r=>r.id===b.route).name}</div>${b.result==='PASS'&&b.delivery==='Awaiting dispatch'?button('Dispatch load','dispatch','small',`data-id="${esc(b.id)}" ${!dispatchEligible(b)?'disabled title="Complete route acceptance, capacity and dates first"':''}`):`<span class="sub">${esc(b.delivery)}</span>`}`:pill(b.delivery,b.delivery==='Blocked'?'amber':'grey')}</td></tr>`).join('')}</tbody></table></div>`;}
function forecast(){const p=project(),v=volume();return heading('PLAN / 01','Project & surplus forecast','Make the surplus visible before excavation starts.',button(icon('plus')+' New project','new-project','primary'))+`<div class="two-col"><section class="panel"><div class="section-title"><h2>Project assumptions</h2>${pill('Planning estimate','grey')}</div><form id="forecast-form"><div class="form-grid"><label class="field">Project name<input name="name" value="${esc(p.name)}" required maxlength="100"></label><label class="field">Location<input name="location" value="${esc(p.location)}" required maxlength="100"></label><label class="field">Expected excavation (t)<input name="excavated" type="number" min="1" max="10000000" step="0.1" value="${p.excavated}" required></label><label class="field">Retained on site (t)<input name="retained" type="number" min="0" max="10000000" step="0.1" value="${p.retained}" required></label><label class="field">Excavation starts<input name="start" type="date" value="${p.start}" required></label><label class="field">Excavation ends<input name="end" type="date" value="${p.end}" required></label><label class="field">Material stream<select name="material">${['Sandy clay','Sand','Gravel','Topsoil'].map(m=>`<option ${m===p.material?'selected':''}>${m}</option>`).join('')}</select></label><label class="field">Bulk density (t/m³)<input name="density" type="number" min="0.5" max="3" step="0.01" value="${p.density}" required><small>Illustrative conversion; confirm with site data.</small></label></div><div class="notice">Changes to material, quantity or dates reopen route acceptance. Previous batch records remain attached to their original routes.</div><button class="btn primary" type="submit">Save forecast</button></form></section><div class="stack"><section class="panel"><div class="eyebrow">AVAILABLE FOR OFF-SITE ROUTING</div><div class="big-number">${num(v)} <small>tonnes</small></div><div class="sub">Approximately ${num(Math.round(v/p.density))} m³ at ${p.density} t/m³</div><div class="fact mt"><span>Total excavation</span><b>${num(p.excavated)} t</b></div><div class="fact mt"><span>Retained on site</span><b>− ${num(p.retained)} t</b></div><div class="thinbar mt"><span style="width:${p.excavated?v/p.excavated*100:0}%"></span></div><div class="progress-label"><span>Off-site surplus</span><span>${Math.round(v/p.excavated*100)}% of excavation</span></div></section><section class="panel"><div class="section-title"><h2>Indicative release profile</h2></div><div class="forecast-bars">${[.2,.35,.3,.15].map((x,i)=>`<div class="bar-group"><b>${num(Math.round(v*x))} t</b><i style="height:${x*240}px"></i><span>Phase ${i+1}</span></div>`).join('')}</div><p class="sub">Planning allocation of 20 / 35 / 30 / 15%. Confirm the release sequence with the project team.</p></section></div></div>`;}
function routeFits(r){return fitsProject(r,project());}
function routePage(){const p=project();return heading('PLAN / 02','One project. Three ways forward.','Compare the full route cost, acceptance conditions and delivery window.',button('Edit forecast','go-forecast'))+`<div class="route-controls"><div class="sub">${esc(p.name)} · ${num(volume())} t ${esc(p.material.toLowerCase())}</div>${pill('Fallback retained independently','grey')}</div><div class="route-grid">${routes.map(r=>`<article class="route-card ${p.route===r.id?'selected':''}"><div class="tag">${icon(r.icon)} &nbsp;${r.label} ${p.route===r.id?'· SELECTED':''}</div><h3>${r.name}</h3><div class="sub">${r.subtitle}</div><h4>${money(cost(r))} <small>NZD estimated</small></h4>${pill(!routeFits(r)?'Capacity / window / material mismatch':accepted(r.id)?'Conditionally accepted':r.id==='local'?'Awaiting receiver sign-off':'Additional evidence required',!routeFits(r)||!accepted(r.id)?'amber':'')}<div class="route-facts"><div class="fact"><span>One-way distance</span><b>${r.distance} km</b></div><div class="fact"><span>Receiving capacity</span><b>${num(r.capacity)} t</b></div><div class="fact"><span>Receiving window</span><b>${r.window}</b></div><div class="fact"><span>Estimated all-in rate</span><b>${'$'+r.rate.toFixed(2)} / t</b></div><div class="fact"><span>Saving vs. fallback</span><b>${money(cost(routes[2])-cost(r))}</b></div></div><div class="progress-label"><span>Acceptance readiness</span><b>${readiness(r.id)}%</b></div><div class="thinbar"><span style="width:${readiness(r.id)}%"></span></div>${button(p.route===r.id?'Review selected route':'Select planning route','select-route',p.route===r.id?'primary':'',`data-id="${r.id}"`)}</article>`).join('')}</div><div class="two-col"><section class="panel"><div class="section-title"><h2>Nearby route network</h2>${pill('Illustrative locations','grey')}</div>${mapView()}</section><section class="panel"><div class="section-title"><h2>A fallback is part of the plan</h2>${icon('check')}</div><p class="sub">Keep a separate disposal pathway available while you prepare local reuse. A field failure triggers a review; it never automatically authorises disposal.</p><div class="route-mini"><span class="route-line">${icon('truck')}</span><div><strong>Regional Fill Facility</strong><div class="sub">${readiness('fallback')}% evidence readiness · ${num(routes[2].capacity)} t capacity</div></div></div><div class="notice">All costs, receiving windows and capacities are scenario assumptions, not quotes or reservations. Confirm acceptance with the receiving site.</div>${button('Review fallback requirements','fallback-evidence')}</section></div>`;}
function evidencePage(){const r=routes.find(r=>r.id===routeFocus),p=project();return heading('PLAN / 03','Acceptance is specific to the receiver.','Collect the right evidence. Record conditions. Keep an accountable trail.')+`<div class="tabbar">${routes.map(x=>`<button class="${x.id===routeFocus?'active':''}" data-action="evidence-route" data-id="${x.id}">${x.label}</button>`).join('')}</div><div class="two-col"><section class="panel"><div class="section-title"><h2>${r.name}</h2>${pill('Receiver-specific checklist','grey')}</div>${requirements.map((q,i)=>`<div class="check-row"><input type="checkbox" id="evidence-${i}" data-evidence="${i}" ${p.evidence[r.id][i]?'checked':''} ${i===5&&state.role!=='Receiver'?'disabled':''}><label for="evidence-${i}">${q}<small>${i===1?'Receiver envelope · '+specOf(r).moistureMin+'–'+specOf(r).moistureMax+'% moisture':i===4?'Receiving window · '+r.window:owners[i]}</small>${p.files[r.id+'-'+i]?`<small>Local evidence note: ${esc(p.files[r.id+'-'+i])}</small>`:''}</label>${pill(p.evidence[r.id][i]?'Recorded':i===5?'Sign-off needed':'Needs review',p.evidence[r.id][i]?'':'amber')}${button(icon('file'),'evidence-note','small',`data-id="${i}" aria-label="Add reference for ${q}"`)}</div>`).join('')}<div class="notice">These are evidence records in a local demo. A checkbox does not certify contamination status, geotechnical suitability or regulatory approval. Field checks only assess conformance to agreed criteria.</div>${state.role!=='Receiver'?button('Switch to Receiver to review sign-off','switch-receiver'):''}</section><div class="stack"><section class="panel center"><div class="eyebrow">ACCEPTANCE READINESS</div><div class="ring" style="--progress:${readiness(r.id)}%"><div class="ring-inner"><strong>${readiness(r.id)}%</strong><small>${complete(r.id)} of 6 complete</small></div></div><h3>${accepted(r.id)?'Conditions recorded':'A few checks before the first load'}</h3><p class="sub">${accepted(r.id)?'Field PASS and a valid receiving window are still required before dispatch.':(6-complete(r.id))+' item(s) remain. Receiver sign-off is separate from on-site verification.'}</p>${pill(accepted(r.id)?'Conditional acceptance':'Not yet accepted',accepted(r.id)?'':'amber')}</section><section class="panel"><div class="section-title"><h2>Named responsibilities</h2></div><div class="fact"><span>Source</span><b>Project manager</b></div><div class="fact mt"><span>Technical evidence</span><b>Consultant / lab</b></div><div class="fact mt"><span>Acceptance</span><b>Receiver site manager</b></div><div class="fact mt"><span>Field conformance</span><b>QA lead</b></div><p class="sub mt">Role switching demonstrates the workflow. This local app does not implement secure organisational permissions.</p></section></div></div>`;}
function materialPage(){const p=project(),env=specOf(selectedRoute());return heading('MATERIAL PASSPORT',p.material+' · '+p.id,'A common material record for the source, receiver and field team.',button('Edit project material','go-forecast'))+`<div class="two-col"><section class="panel"><div class="section-title"><h2>Forecast material profile</h2>${pill('Pre-characterisation','grey')}</div><div class="project-stats"><div><span>Forecast quantity</span><strong>${num(volume())} t</strong></div><div><span>Source project</span><strong>${esc(p.name)}</strong></div><div><span>Availability</span><strong>${shortDate(p.start)} – ${shortDate(p.end)}</strong></div></div><h3>Reference sample composition</h3><div class="material-band" role="img" aria-label="Illustrative reference sample: 42 percent fines, 38 percent sand, 20 percent gravel"><span style="width:42%"></span><span style="width:38%"></span><span style="width:20%"></span></div><div class="legend"><span>Fines 42%</span><span>Sand 38%</span><span>Gravel 20%</span></div><div class="notice">Reference sample for the seeded sandy-clay scenario. Changing the material stream requires new characterisation; these percentages are not a test result for a new material.</div><div class="table-wrap"><table><thead><tr><th>Parameter</th><th>${esc(selectedRoute().name)} envelope</th><th>Source</th></tr></thead><tbody><tr><td>Moisture content</td><td>${env.moistureMin}–${env.moistureMax}%</td><td>Receiving site criteria</td></tr><tr><td>Fines fraction</td><td>${env.finesMin}–${env.finesMax}%</td><td>Receiving site criteria</td></tr><tr><td>Visual anomalies</td><td>None observed</td><td>Field inspection</td></tr><tr><td>Contamination clearance</td><td>External evidence required</td><td>Consultant / laboratory</td></tr></tbody></table></div></section><div class="stack"><section class="panel"><div class="section-title"><h2>Evidence follows the material</h2>${icon('file')}</div><p class="sub">Each receiving route has its own requirements. Review current evidence before accepting material or releasing a batch.</p>${button('Open evidence checklist','go-evidence','primary')}</section><section class="panel"><div class="eyebrow">TRACEABILITY</div><h3>${p.batches.length} recorded batches</h3><p class="sub">Source → material profile → receiver conditions → field result → delivery record.</p>${button('View field records','go-verification')}</section></div></div>`;}
function verificationPage(){const p=project(),r=selectedRoute();return heading('FIELD / 04','Verify the batch. Then move it.','On-site conformance against the selected receiver’s agreed envelope.')+`<div class="two-col"><section class="panel"><div class="section-title"><h2>New batch check</h2>${pill(r.name,'grey')}</div><form id="batch-form"><div class="form-grid"><label class="field">Batch ID<input name="id" required value="B-${String(220+p.batches.length-3).padStart(4,'0')}" maxlength="30"></label><label class="field">Batch mass (t)<input name="mass" required type="number" min="0.1" max="40" step="0.1" value="18.4"></label><label class="field">Moisture (%)<input name="moisture" required type="number" min="0" max="100" step="0.1" value="14"><small>Receiver range: ${specOf(r).moistureMin}–${specOf(r).moistureMax}%</small></label><label class="field">Fines fraction (%)<input name="fines" required type="number" min="0" max="100" step="0.1" value="42"><small>Receiver range: ${specOf(r).finesMin}–${specOf(r).finesMax}%</small></label><label class="field full">Visual inspection<select name="visual"><option value="clear">No unexpected material observed</option><option value="uncertain">Uncertain — inspection needed</option><option value="anomaly">Unexpected material / suspected contamination</option></select></label></div><div class="notice">PASS is conformance to a demo specification, not contamination certification or permission to haul. HOLD and FAIL batches cannot be dispatched.</div><button class="btn primary" type="submit">${icon('check')} Check & record batch</button></form>${batchResult?`<div class="verify-result ${batchResult.result}" role="status"><strong>${batchResult.result} · ${esc(batchResult.id)}</strong><p>${esc(batchResult.reason)}</p><p>${batchResult.result==='PASS'?'Dispatch is available after route acceptance, capacity and date checks.':batchResult.result==='HOLD'?'Isolate this batch and arrange a retest. Record the retest as a new batch.':'Quarantine this batch and refer to the responsible consultant. Review fallback acceptance separately.'}</p></div>`:''}</section><div class="stack"><section class="panel"><div class="section-title"><h2>Release gate</h2></div><div class="check-row">${icon('check')}<div><b style="font-size:14px">Receiver acceptance</b><div class="sub">${complete(r.id)} / 6 requirements recorded</div></div>${pill(accepted(r.id)?'Complete':'Blocked',accepted(r.id)?'':'amber')}</div><div class="check-row">${icon('calendar')}<div><b style="font-size:14px">Material, capacity & window</b><div class="sub">${r.window} · ${num(r.capacity)} t</div></div>${pill(routeFits(r)?'Aligned':'Review',routeFits(r)?'':'amber')}</div><div class="check-row">${icon('layers')}<div><b style="font-size:14px">Batch-specific conformance</b><div class="sub">A PASS is required for each load.</div></div></div>${button('Review acceptance','go-evidence','small')}</section><section class="panel"><h3 class="m0">A controlled pause is a useful result.</h3><p class="sub">HOLD → segregate and retest.<br><br>FAIL → quarantine and investigate.<br><br>Fallback → confirm independent suitability before considering another destination.</p>${button('Review fallback route','fallback-evidence','small')}</section></div></div><section class="panel mt"><div class="section-title"><h2>Batch register</h2>${pill(p.batches.length+' records','grey')}</div>${batchTable([...p.batches].reverse())}</section>`;}
function dispatchEligible(b){const r=routes.find(r=>r.id===b.route),alreadyRouted=state.projects.flatMap(p=>p.batches).filter(x=>x.route===b.route&&['Delivered','In transit'].includes(x.delivery)).reduce((n,x)=>n+x.mass,0);return alreadyRouted+b.mass<=r.capacity&&state.role==='Supplier'&&b.result==='PASS'&&conformsCurrent(b,r)&&accepted(r.id)&&routeFits(r)&&b.delivery==='Awaiting dispatch'&&project().batches.filter(x=>x.delivery==='Delivered'||x.delivery==='In transit').reduce((s,x)=>s+x.mass,0)+b.mass<=volume();}
function deliveriesPage(){const p=project(),loads=p.batches.filter(b=>['In transit','Delivered'].includes(b.delivery));return heading('LOGISTICS / 05','Every load has a destination.','Track verified loads from site release to receiver acknowledgement.',button('Record another batch','go-verification','primary'))+`<section class="metrics">${metric('Delivered',num(loads.filter(x=>x.delivery==='Delivered').reduce((s,x)=>s+x.mass,0)),'t','Receiver-acknowledged demo loads','truck')}${metric('In transit',loads.filter(x=>x.delivery==='In transit').length,'loads','Manually advanced demo progress','route')}${metric('Awaiting dispatch',p.batches.filter(x=>x.delivery==='Awaiting dispatch').length,'loads','Release checks apply','clock')}${metric('Held at source',p.batches.filter(x=>x.result!=='PASS').length,'batches','Excluded from dispatch','check',true)}</section><div class="notice">Local delivery simulation. Updates below are recorded manually; no carrier GPS, live truck feed or external booking is connected. Seeded historic loads are illustrative records.</div><div class="stack">${loads.length?loads.slice().reverse().map(b=>`<article class="panel"><div class="section-title"><div><div class="eyebrow">${esc(b.id)} · ${num(b.mass)} TONNES</div><h2 style="margin-top:5px">${esc(p.name)} to ${routes.find(r=>r.id===b.route).name}</h2></div>${pill(b.delivery,b.delivery==='In transit'?'amber':'')}</div><div class="delivery-step"><b>Verified</b><span class="done"></span><b>Dispatched</b><span class="${b.delivery==='Delivered'?'done':''}"></span><b>Received</b></div><div class="export-box"><div class="sub">${esc(b.time)} · ${b.result} · ${routes.find(r=>r.id===b.route).distance} km one-way route</div>${b.delivery==='In transit'?button('Acknowledge receipt (demo)','receive','primary small',`data-id="${esc(b.id)}"`):pill('Delivery record complete')}</div></article>`).join(''):'<div class="panel empty">No loads dispatched yet. Verify a batch and complete route acceptance.</div>'}</div><section class="panel mt"><div class="section-title"><h2>Dispatch queue</h2></div>${batchTable(p.batches.filter(b=>b.delivery==='Awaiting dispatch'))}</section>`;}
function impactPage(){const p=project(),r=selectedRoute(),delivered=p.batches.filter(x=>x.delivery==='Delivered'),reuse=delivered.filter(x=>x.route!=='fallback').reduce((s,x)=>s+x.mass,0),tkm=delivered.reduce((s,b)=>s+b.mass*(70-routes.find(r=>r.id===b.route).distance),0),savings=delivered.reduce((s,b)=>s+b.mass*(routes[2].rate-routes.find(r=>r.id===b.route).rate),0);return heading('IMPACT / REPORTING','Better routes. Measurable outcomes.','Separate planning potential from acknowledged deliveries.',button(icon('download')+' Export project report','export','primary'))+`<section class="metrics">${metric('Delivered to reuse',num(reuse),'t','Acknowledged local + alternative loads','leaf')}${metric('Modelled saving',money(savings),'','Delivered loads × assumed rate difference','money')}${metric('Avoided tonne-km',num(Math.round(tkm)),'','Delivered mass × distance difference','route')}${metric('Modelled CO₂e avoided',num(tkm*.1/1000),'t','Illustrative factor: 0.10 kg / tonne-km','chart')}</section><div class="two-col"><section class="panel"><div class="section-title"><h2>Plan-level cost comparison</h2>${pill(num(volume())+' t forecast','grey')}</div><div class="cost-chart">${routes.map(x=>`<div class="cost-row"><div class="fact"><span>${x.label} · ${x.distance} km</span><strong>${money(cost(x))}</strong></div><div class="cost-track"><div style="width:${x.rate/routes[2].rate*100}%"></div></div></div>`).join('')}</div><div class="notice">Potential saving on selected route: <b>${money(cost(routes[2])-cost(r))}</b>. This is a scenario estimate, not an actual invoice saving.</div></section><section class="panel"><div class="section-title"><h2>Transparent assumptions</h2></div><p class="sub">All-in rates include an illustrative allowance for transport, receiving/disposal and coordination. They are not supplier quotations.</p><div class="fact mt"><span>Local / alternative / fallback</span><b>$25 / $31 / $56.45 per t</b></div><div class="fact mt"><span>Distances</span><b>8 / 17 / 70 km, one way</b></div><div class="fact mt"><span>Emissions factor</span><b>0.10 kg CO₂e / t-km</b></div><p class="sub mt">CO₂e excludes empty return trips, loading, idling, material processing and embodied impacts. Replace the illustrative factor and distances with verified project inputs before external reporting.</p><p class="sub">No claim of avoided virgin material is made without evidence of substitution at the receiving site.</p></section></div><section class="panel mt"><div class="section-title"><h2>Project audit trail</h2></div>${activity()}</section>`;}
const sources=[{id:'SRC-01',name:'Warkworth Development',material:'Sandy clay',mass:1240,distance:8,start:'2026-10-14',end:'2026-10-28',readiness:83},{id:'SRC-02',name:'Silverdale Utility Corridor',material:'Sand',mass:420,distance:24,start:'2026-10-18',end:'2026-10-25',readiness:67},{id:'SRC-03',name:'Mahurangi Access Works',material:'Gravel',mass:680,distance:17,start:'2026-10-16',end:'2026-10-30',readiness:50}];
function sourceCatalog(){const p=state.projects.find(x=>x.id==='RG-024');return sources.map(s=>s.id==='SRC-01'&&p?{...s,name:p.name,material:p.material,mass:Math.max(0,p.excavated-p.retained),start:p.start,end:p.end,readiness:Math.round(p.evidence.local.filter(Boolean).length/6*100)}:s);}
function legacySourcesPage(){const matches=sourceCatalog().filter(s=>(searchState.material==='Any material'||s.material===searchState.material)&&s.distance<=searchState.radius&&s.mass>=searchState.quantity&&s.start<=searchState.start&&s.end>=searchState.end);return heading('RECEIVER WORKSPACE','Find material that fits your programme.','Start with the receiving window and specification, then review the evidence.')+`<form class="filterbar" id="source-filter"><label class="field">Material<select name="material">${['Any material','Sandy clay','Sand','Gravel','Topsoil'].map(x=>`<option ${x===searchState.material?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Required quantity (t)<input type="number" name="quantity" min="1" value="${searchState.quantity}" required></label><label class="field">Within (km)<input type="number" name="radius" min="1" max="500" value="${searchState.radius}" required></label><label class="field">Receive from<input type="date" name="start" value="${searchState.start}" required></label><label class="field">Receive until<input type="date" name="end" value="${searchState.end}" required></label><button class="btn primary" type="submit">Find sources</button></form><div class="section-title"><h2>${matches.length} matching source${matches.length!==1?'s':''}</h2>${pill('Demo listings · Auckland','grey')}</div><div class="route-grid">${matches.map(s=>`<article class="receiver-card"><div class="eyebrow">${s.distance} KM AWAY · ${s.id}</div><h3>${s.name}</h3><div class="sub">${s.material} · ${num(s.mass)} t forecast available</div><div class="route-facts"><div class="fact"><span>Availability</span><b>${shortDate(s.start)} – ${shortDate(s.end)}</b></div><div class="fact"><span>Evidence readiness</span><b>${s.readiness}%</b></div></div><div class="thinbar"><span style="width:${s.readiness}%"></span></div><p class="sub">Subject to your acceptance criteria and batch conformance.</p>${button(state.requests.some(x=>x.source===s.id)?'View local request':'Request material','request-material','primary',`data-id="${s.id}"`)}</article>`).join('')||'<div class="panel empty full">No sources match these requirements. Try a wider radius or a smaller quantity.</div>'}</div>${state.requests.length?`<section class="panel"><div class="section-title"><h2>Your material requests</h2>${pill('Saved locally · not sent','amber')}</div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Quantity</th><th>Receiving window</th><th>Status</th></tr></thead><tbody>${state.requests.map(x=>`<tr><td>${sources.find(s=>s.id===x.source).name}</td><td>${num(x.quantity)} t</td><td>${shortDate(x.start)} – ${shortDate(x.end)}</td><td>${pill('Draft request','grey')}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function legacyNavigate(next){page=next;if(next==='evidence')routeFocus=project().route;render();window.scrollTo({top:0});$('#main').focus({preventScroll:true});}
function modal(content){$('#dialog').innerHTML=content;$('#dialog').showModal();}
function modalHeader(title,desc=''){return `<div class="modal-top"><div><h2>${title}</h2>${desc?`<p class="sub">${desc}</p>`:''}</div><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`;}
function legacyOnboarding(){modalRole=state.role;modal(modalHeader('Your role. Your route.','Set up a local organisation workspace. You can switch roles at any time.')+`<div class="onboarding-options"><button class="role-option ${modalRole==='Supplier'?'chosen':''}" data-action="choose-role" data-id="Supplier">${icon('project')}<h3>I have surplus</h3><p>Civil contractors, developers, councils and infrastructure teams.<br><br>Forecast material and plan its destination.</p></button><button class="role-option ${modalRole==='Receiver'?'chosen':''}" data-action="choose-role" data-id="Receiver">${icon('layers')}<h3>I need material</h3><p>Receiving sites, landscapers and material processors.<br><br>Find a source and define acceptance.</p></button></div><form id="onboarding-form"><label class="field">Organisation name<input name="org" value="${esc(state.org)}" required maxlength="70"></label><label class="field">Organisation type<select name="orgType"><option>Civil / earthworks contractor</option><option>Developer</option><option>Council / infrastructure project team</option><option>Receiving site</option><option>Landscaper / material processor</option></select></label><p class="sub">This is a local demonstration workspace. Changes stay in this browser; no account or external messages are created.</p><div class="modal-actions"><button class="btn primary" type="submit">Open ${modalRole.toLowerCase()} workspace</button></div></form>`);}
function newProject(){modal(modalHeader('Plan a new project','Begin with what you know. Refine the forecast as evidence arrives.')+`<form id="new-project-form"><label class="field">Project name<input name="name" required maxlength="100" placeholder="e.g. Northern Link earthworks"></label><label class="field">Site location<input name="location" required maxlength="100" placeholder="Town / region"></label><div class="form-grid"><label class="field">Expected surplus (t)<input name="quantity" required type="number" min="1" max="10000000" step="0.1" value="1000"></label><label class="field">Material<select name="material"><option>Sandy clay</option><option>Sand</option><option>Gravel</option><option>Topsoil</option></select></label><label class="field">Start date<input name="start" required type="date" value="2026-10-14"></label><label class="field">End date<input name="end" required type="date" value="2026-10-28"></label></div><div class="modal-actions">${button('Cancel','close')}<button class="btn primary" type="submit">Create project</button></div></form>`);}
function exportReport(){const p=project(),r=selectedRoute();const rows=[['ReGround local demonstration report'],['Project',p.name],['Location',p.location],['Exported (NZ)',stamp()],['Forecast surplus (t)',volume()],['Selected route',r.name],['Estimated total NZD',cost(r)],['Readiness (%)',readiness(r.id)],['Assumptions','Demo rates: local $25/t, alternative $31/t, fallback $56.45/t; one-way distance 8/17/70 km; emissions 0.10 kg CO2e/t-km. Not verified project data.'],[],['Batch ID','Mass (t)','Moisture (%)','Fines (%)','QA result','Route','Delivery','Recorded']];p.batches.forEach(b=>rows.push([b.id,b.mass,b.moisture,b.fines,b.result,b.route,b.delivery,b.time]));rows.push([],['Audit message','NZ time']);p.log.forEach(x=>rows.push([x.message,x.time]));const csv='\uFEFF'+rows.map(row=>row.map(x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='ReGround-'+p.id+'-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Project report exported. Includes scenario assumptions.');}
document.addEventListener('click',e=>{const pg=e.target.closest('[data-page]');if(pg){navigate(pg.dataset.page);return;}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'menu':$('.sidebar').classList.toggle('open');break;case'close':$('#dialog').close();break;case'onboarding':onboarding();break;case'choose-role':modalRole=id;document.querySelectorAll('.role-option').forEach(x=>x.classList.toggle('chosen',x.dataset.id===id));$('#onboarding-form button[type=submit]').textContent='Open '+id.toLowerCase()+' workspace';break;case'new-project':newProject();break;case'focus-route':routeFocus=id;render();break;case'select-route':project().route=id;routeFocus=id;log('Planning route selected: '+routes.find(r=>r.id===id).name);persist();page='evidence';render();break;case'evidence-route':routeFocus=id;render();break;case'fallback-evidence':page='evidence';routeFocus='fallback';render();break;case'go-forecast':navigate('forecast');break;case'go-evidence':navigate('evidence');break;case'go-verification':navigate('verification');break;case'find-sources':navigate('sources');break;case'switch-receiver':if(routeFocus!=='fallback')state.siteId=routeFocus;state.reviewProjectId=project().id;switchWorkspace('Receiver','approvals');break;case'evidence-note':modal(modalHeader('Evidence reference',requirements[+id])+`<form id="evidence-note-form" data-index="${id}"><label class="field">Document reference / review note<textarea name="note" required maxlength="1000" placeholder="Report ID, reviewer, date and conditions">${esc(project().files[routeFocus+'-'+id]||'')}</textarea></label><p class="sub">Stores a reference note locally. Original documents must remain in your organisation’s document system.</p><button class="btn primary" type="submit">Save reference</button></form>`);break;case'dispatch':{const batch=project().batches.find(x=>x.id===id);if(!dispatchEligible(batch)){toast('Dispatch blocked: acceptance, fit or remaining tonnage needs review.');break;}batch.delivery='In transit';batch.time=stamp();log(batch.id+' dispatched to '+routes.find(r=>r.id===batch.route).name+' (demo)');persist();render();toast('Demo load dispatched. Track it in Deliveries.');break;}case'receive':{const batch=project().batches.find(x=>x.id===id);batch.delivery='Delivered';batch.time=stamp();log(batch.id+' receipt acknowledged (demo)');persist();render();toast('Receipt recorded. Impact metrics updated.');break;}case'export':exportReport();break;case'request-material':{const s=sourceCatalog().find(x=>x.id===id),existing=state.requests.find(x=>x.source===id);modal(modalHeader(existing?'Your local material request':'Request '+s.material,s.name+' · '+num(s.mass)+' t forecast')+`<form id="request-form" data-source="${id}"><div class="form-grid"><label class="field">Quantity (t)<input type="number" min="1" max="${s.mass}" name="quantity" value="${existing?.quantity||searchState.quantity}" required></label><label class="field">Intended use<input name="use" value="${esc(existing?.use||'Engineered fill')}" required maxlength="160"></label><label class="field">Receive from<input type="date" name="start" value="${existing?.start||searchState.start}" required></label><label class="field">Receive until<input type="date" name="end" value="${existing?.end||searchState.end}" required></label></div><label class="field">Acceptance conditions<textarea name="conditions" required maxlength="1000" placeholder="Specify material requirements, evidence and site access conditions">${esc(existing?.conditions||'Subject to consultant evidence, receiver sign-off and batch conformance.')}</textarea></label><div class="notice">Saves a local draft request. No reservation is made and nothing is sent to the supplier.</div><button type="submit" class="btn primary">Save local request</button></form>`);break;}}});
document.addEventListener('change',e=>{if(e.target.id==='role-switch'){switchWorkspace(e.target.value);return;}if(e.target.id==='project-select'){state.projectId=e.target.value;routeFocus=project().route;batchResult=null;persist();render();$('#project-select')?.focus();}if(e.target.matches('[data-evidence]')){const i=+e.target.dataset.evidence,p=project();if(i===5&&state.role!=='Receiver')return;if(i===5&&e.target.checked&&p.evidence[routeFocus].slice(0,5).some(x=>!x)){e.target.checked=false;toast('Record all five supporting requirements before receiver sign-off.');return;}p.evidence[routeFocus][i]=e.target.checked;if(i<5&&!e.target.checked)p.evidence[routeFocus][5]=false;log(requirements[i]+': '+(e.target.checked?'recorded':'reopened')+' · '+routes.find(r=>r.id===routeFocus).name);persist();render();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));switch(f.getAttribute('id')){case'onboarding-form':if(!d.org.trim())return;state.org=d.org.trim();state.orgType=d.orgType;state.role=modalRole;state.onboarded=true;persist();$('#dialog').close();navigate(state.role==='Receiver'?'sources':'dashboard');toast('Your local '+state.role.toLowerCase()+' workspace is ready.');break;case'new-project-form':{if(d.end<d.start){toast('End date must be on or after the start date.');return;}if(!d.name.trim()||!d.location.trim()){toast('Enter a project name and location.');return;}const p=seedProject();p.id='RG-'+String(Date.now()).slice(-7);Object.assign(p,{name:d.name.trim(),location:d.location.trim(),material:d.material,excavated:+d.quantity,retained:0,start:d.start,end:d.end,batches:[],log:[],evidence:{local:Array(6).fill(false),alternative:Array(6).fill(false),fallback:Array(6).fill(false)}});state.projects.push(p);state.projectId=p.id;log('Project created with initial forecast');persist();$('#dialog').close();navigate('forecast');toast('Project created. Refine the forecast and acceptance evidence.');break;}case'forecast-form':{if(+d.retained>+d.excavated){toast('Retained quantity cannot exceed excavation quantity.');return;}if(d.end<d.start){toast('End date must be on or after the start date.');return;}const p=project(),changed=['material','excavated','retained','start','end','location'].some(k=>String(p[k])!==String(d[k]));Object.assign(p,{name:d.name.trim(),location:d.location.trim(),excavated:+d.excavated,retained:+d.retained,density:+d.density,start:d.start,end:d.end,material:d.material});if(changed)routes.forEach(r=>{p.evidence[r.id][5]=false;});log('Forecast updated'+(changed?'; receiver acceptance reopened':''));persist();render();toast('Forecast saved'+(changed?'. Receiver sign-off must be reviewed.':'.'));break;}case'evidence-note-form':project().files[routeFocus+'-'+f.dataset.index]=d.note.trim();log('Evidence reference added: '+requirements[+f.dataset.index]);persist();$('#dialog').close();render();toast('Reference saved locally.');break;case'batch-form':{const p=project(),r=selectedRoute();if(p.batches.some(x=>x.id.toLowerCase()===d.id.trim().toLowerCase())){toast('Batch ID already exists. Use a unique ID for a new check.');return;}if(!d.id.trim()){toast('Enter a batch ID.');return;}let result='PASS',reason='Within agreed receiver envelope';if(d.visual==='anomaly'){result='FAIL';reason='Unexpected material observed; quarantine and seek consultant review';}else if(d.visual==='uncertain'||+d.moisture<specOf(r).moistureMin||+d.moisture>(specOf(r).moistureMax)||+d.fines<specOf(r).finesMin||+d.fines>specOf(r).finesMax||p.material!==specOf(r).material){result='HOLD';reason=p.material!==specOf(r).material?'Material stream needs its own agreed specification':'Outside agreed envelope or inspection incomplete; isolate and retest';}batchResult={id:d.id.trim(),mass:+d.mass,moisture:+d.moisture,fines:+d.fines,visual:d.visual,result,reason,route:r.id,delivery:result==='PASS'?'Awaiting dispatch':'Blocked',time:stamp()};p.batches.push({...batchResult});log(batchResult.id+' recorded: '+result);persist();render();break;}case'source-filter':if(d.end<d.start){toast('Receiving end must be on or after start.');return;}searchState={material:d.material,radius:+d.radius,quantity:+d.quantity,start:d.start,end:d.end};render();break;case'request-form':{const s=sourceCatalog().find(x=>x.id===f.dataset.source);if(d.start<s.start||d.end>s.end||d.end<d.start){toast('Choose dates within the source availability window.');return;}const req={source:s.id,quantity:+d.quantity,use:d.use.trim(),start:d.start,end:d.end,conditions:d.conditions.trim()};state.requests=state.requests.filter(x=>x.source!==s.id);state.requests.push(req);persist();$('#dialog').close();render();toast('Local draft saved. Nothing has been sent.');break;}}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_reground_project',description:'Read the active local demo project forecast and route acceptance state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return receiver()?{role:'Receiver',site:site().name,requiredTonnes:site().required,receivedTonnes:receivedMass(),incomingTonnes:transitMass(),pendingSourceReviews:pendingReviews().length,demo:true}:{role:'Supplier',id:project().id,name:project().name,surplusTonnes:volume(),route:project().route,readiness:readiness(project().route),demo:true};}})).catch(()=>{});}catch{}}

