try{const v2=JSON.parse(localStorage.getItem(storageKey));if(v2?.version===2&&v2.projects?.length)state=v2;}catch{}
state.version=2;
state.profiles ||= {Supplier:{org:state.org||'Northland Civil',type:'Civil / earthworks contractor',contact:'Project manager'},Receiver:{org:'Warkworth Infrastructure',type:'Receiving site / infrastructure project',contact:'Receiving site manager'}};
state.receivingSites ||= [{id:'local',name:'Warkworth North',location:'Warkworth, Auckland',required:800,capacity:1600,material:'Sandy clay',use:'Engineered fill',start:'2026-10-14',end:'2026-10-28',moistureMin:10,moistureMax:18,finesMin:30,finesMax:50,log:[]},{id:'alternative',name:'Mahurangi Landscape',location:'Mahurangi, Auckland',required:600,capacity:1400,material:'Sandy clay',use:'Landscape earthworks',start:'2026-10-14',end:'2026-10-28',moistureMin:10,moistureMax:16,finesMin:30,finesMax:50,log:[]}];
state.receivingSites.forEach(s=>{s.profile ||= s.id==='local'?{...state.profiles.Receiver}:{org:'Mahurangi Landscape Ltd',type:'Landscaper / material processor',contact:'Receiving site manager'};});
state.siteId ||= 'local';state.lastPages ||= {Supplier:'dashboard',Receiver:'dashboard'};
state.requests.forEach(x=>{x.siteId ||= 'local';if(x.source==='SRC-01')x.source='PROJECT-RG-024';});
state.org=state.profiles[state.role].org;
let navOpen=false,returnFocus=null;
const receiver=()=>state.role==='Receiver';
const site=()=>state.receivingSites.find(s=>s.id===state.siteId)||state.receivingSites[0];
const workspaceProfile=()=>receiver()?site().profile:state.profiles.Supplier;
const specOf=r=>state.receivingSites.find(s=>s.id===r.id)||{material:'Sandy clay',start:'2026-10-14',end:'2026-10-31',capacity:5000,moistureMin:10,moistureMax:18,finesMin:30,finesMax:50};
function syncRoutes(){routes.forEach(r=>{const s=specOf(r);r.capacity=s.capacity;r.window=shortDate(s.start)+' '+s.start.slice(0,4)+' – '+shortDate(s.end)+' '+s.end.slice(0,4);if(r.id!=='fallback')r.name=s.name;});}
function fitsProject(r,p){const s=specOf(r);return p.excavated-p.retained<=s.capacity&&p.start>=s.start&&p.end<=s.end&&p.material===s.material;}
function conformsCurrent(b,r){const s=specOf(r);return b.moisture>=s.moistureMin&&b.moisture<=s.moistureMax&&b.fines>=s.finesMin&&b.fines<=s.finesMax&&(!b.visual||b.visual==='clear');}
function siteBatches(){return state.projects.flatMap(p=>p.batches.filter(b=>b.route===site().id).map(b=>({...b,projectId:p.id,projectName:p.name})));}
const receivedMass=()=>siteBatches().filter(b=>b.delivery==='Delivered').reduce((n,b)=>n+b.mass,0);
const transitMass=()=>siteBatches().filter(b=>b.delivery==='In transit').reduce((n,b)=>n+b.mass,0);
const siteProjects=()=>state.projects.filter(p=>p.route===site().id||p.evidence[site().id]?.slice(0,5).some(Boolean));
const siteDrafts=()=>state.requests.filter(r=>r.siteId===site().id);
const pendingReviews=()=>siteProjects().filter(p=>!p.evidence[site().id][5]);
function navigation(){return receiver()?[['dashboard','grid','Receiving overview'],['receiving-plan','calendar','Site requirements'],['sources','search','Find material'],['approvals','check','Source approvals'],['inbound','truck','Incoming deliveries'],['received','layers','Received material'],['receiver-impact','chart','Receiving report']]:[['dashboard','grid','Supply overview'],['forecast','project','Projects & forecast'],['routes','route','Plan soil routes'],['evidence','file','Prepare evidence'],['material','layers','Material profile'],['verification','check','Verify & release'],['deliveries','truck','Outgoing deliveries'],['impact','chart','Project impact']];}
function render(){syncRoutes();const n=navigation();if(!n.some(x=>x[0]===page))page='dashboard';const prof=workspaceProfile(),title=n.find(x=>x[0]===page)[2];$('#app').innerHTML=`<aside id="workspace-navigation" class="sidebar ${navOpen?'open':''}" ${navOpen?'role="dialog" aria-modal="true"':''} aria-label="${state.role} workspace navigation"><div class="brand"><span class="brandmark">»</span>ReGround<span class="version-mark">V2</span></div><div class="brand-sub">KNOW THE ROUTE BEFORE YOU DIG.</div><button class="drawer-close" data-action="close-nav" aria-label="Close navigation">×</button><section class="workspace-identity ${receiver()?'receiver-identity':''}" aria-label="Current organisation and role"><div class="identity-label">YOU ARE WORKING AS</div><div class="identity-role">${icon(receiver()?'layers':'project')} ${state.role}</div><div class="identity-purpose">${receiver()?'I need material · Receiving team':'I have surplus · Source team'}</div><div class="identity-divider"></div><strong>${esc(prof.org)}</strong><span>${esc(prof.type)}</span><small>${receiver()?'Receiving site: '+esc(site().name):'Source project: '+esc(project().name)}</small><button class="text-btn" data-action="profile-edit">Edit ${state.role.toLowerCase()} details</button></section><div class="nav-label">${receiver()?'RECEIVING WORKSPACE':'SUPPLY WORKSPACE'}</div><nav class="nav" aria-label="${state.role} tasks">${n.map(([id,ic,label])=>`<button type="button" data-page="${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='approvals'&&pendingReviews().length?`<span class="count" aria-label="${pendingReviews().length} reviews pending">${pendingReviews().length}</span>`:id==='evidence'&&6-complete(project().route)?`<span class="count" aria-label="${6-complete(project().route)} requirements remaining">${6-complete(project().route)}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-tip"><strong>${receiver()?'Accept with confidence.':'Plan before excavation.'}</strong><span>${receiver()?'Set criteria → review evidence → receive loads.':'Forecast → secure a route → verify → dispatch.'}</span></div><button class="user-btn" data-action="onboarding">${icon('building')}<span>Workspace setup<small>Organisation & role details</small></span></button></div></aside>${navOpen?'<button class="nav-scrim" data-action="close-nav" aria-label="Close navigation overlay"></button>':''}<div class="shell" ${navOpen?'inert':''}><header class="topbar v2-topbar"><div class="crumb"><button class="mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="${navOpen}" aria-controls="workspace-navigation">${icon('menu')}</button><span class="workspace-context">${receiver()?'Receiving':'Supply'} workspace</span><strong>${title}</strong></div><div class="top-context"><label class="context-selector"><span>${receiver()?'Receiving site':'Source project'}</span>${receiver()?`<select id="site-select" aria-label="Receiving site">${state.receivingSites.map(s=>`<option value="${s.id}" ${site().id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:`<select id="project-select" aria-label="Source project">${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===project().id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}</label><div class="role-control" role="group" aria-label="Choose your working role"><span class="control-label">WORKING ROLE</span><div class="role-buttons"><button data-action="set-role" data-id="Supplier" aria-pressed="${!receiver()}" class="${!receiver()?'selected':''}">${icon('project')}<span>Supplier<small>I have surplus</small></span></button><button data-action="set-role" data-id="Receiver" aria-pressed="${receiver()}" class="${receiver()?'selected':''}">${icon('layers')}<span>Receiver<small>I need material</small></span></button></div></div></div></header><main id="main" class="main v2-main" tabindex="-1"><div class="workspace-strip"><span>${pill(state.role+' view',receiver()?'clay':'')} ${esc(receiver()?site().name:project().name)}</span><span>Local demo · V2 · Changes saved on this device</span></div>${renderPage()}<footer class="footer-note"><span>REGROUND · ${receiver()?'SPECIFY → REVIEW → ACCEPT → RECEIVE':'FORECAST → PLAN → VERIFY → DISPATCH'}</span><span>Illustrative Auckland scenario · NZD excl. GST</span></footer></main></div>`;if(navOpen)setTimeout(()=>$('.drawer-close')?.focus(),0);}
function renderPage(){if(receiver())return ({dashboard:receiverDashboard,'receiving-plan':receivingPlan,sources:sourcesPage,approvals:approvalPage,inbound:inboundPage,received:receivedPage,'receiver-impact':receiverImpact}[page]||receiverDashboard)();let content=legacyRenderPage();if(page==='dashboard'){content=content.replace(/<section class="hero">[\s\S]*?<\/section>/,'').replace('Your ground. A clearer path.','Plan your surplus. Keep excavation moving.').replace('A little planning above ground. A lot less uncertainty below.','Choose a destination, prepare the evidence and release verified loads.');}if(page==='deliveries'){content=content.replace(/<button type="button" class="btn primary small" data-action="receive"[^>]*>[\s\S]*?<\/button>/g,pill('Awaiting receiver acknowledgement','amber'));}return content;}
// Keep the original page dispatcher, using the original supply dashboard.
function dashboard(){return legacyDashboard();}
function navigate(next){const allowed=navigation().some(n=>n[0]===next);if(!allowed){next=receiver()?'approvals':'evidence';}navOpen=false;page=next;state.lastPages[state.role]=page;if(!receiver()&&page==='evidence')routeFocus=project().route;persist();render();window.scrollTo({top:0});$('#main').focus({preventScroll:true});}
function switchWorkspace(role,next){if(!['Supplier','Receiver'].includes(role))return;state.lastPages[state.role]=page;state.role=role;state.org=workspaceProfile().org;routeFocus=receiver()?site().id:project().route;batchResult=null;navOpen=false;page=next||state.lastPages[role]||'dashboard';persist();render();$('#main').focus({preventScroll:true});toast(role==='Receiver'?'Receiver view: site requirements, source reviews and incoming loads.':'Supplier view: surplus forecast, route planning and outgoing loads.');}
function receiverDashboard(){const s=site(),received=receivedMass(),incoming=transitMass(),gap=Math.max(0,s.required-received-incoming),pending=pendingReviews();return heading('RECEIVER / SITE CONTROL','The right material. Ready for your site.','Review source conditions and plan incoming material for '+esc(s.name)+'.',button('Edit receiving requirements','open-plan','primary'))+`<section class="metrics">${metric('Material still needed',num(gap),'t',num(s.required)+' t target − received − in transit','layers')}${metric('Received at this site',num(received),'t','Acknowledged loads only','check')}${metric('Incoming material',num(incoming),'t',siteBatches().filter(b=>b.delivery==='In transit').length+' loads awaiting receipt','truck')}${metric('Sources to review',pending.length,'',pending.length?'Your sign-off is the next step':'No source reviews awaiting sign-off','file')}</section><section class="next-action"><div class="next-action-icon">${icon(pending.length?'file':incoming?'truck':'search')}</div><div><div class="eyebrow">YOUR NEXT ACTION</div><h2>${pending.length?'Review '+pending.length+' source proposal'+(pending.length===1?'':'s'):incoming?'Acknowledge incoming loads':'Find a source for your receiving window'}</h2><p>${pending.length?'Check supplier evidence against your site criteria before recording conditional acceptance.':incoming?'Confirm arrival and received mass. Only acknowledged loads count as received.':'Use material, quantity and dates from your receiving plan.'}</p></div>${button(pending.length?'Review sources':incoming?'View incoming loads':'Find material',pending.length?'open-approvals':incoming?'open-inbound':'find-sources','primary')}</section><div class="two-col mt"><section class="panel"><div class="section-title"><h2>Your receiving plan</h2>${pill('Receiver-owned criteria','clay')}</div><div class="project-head"><div><div class="eyebrow">${esc(s.location)}</div><h3>${esc(s.name)}</h3><div class="sub">${esc(s.use)}</div></div>${pill(s.material,'grey')}</div><div class="project-stats"><div><span>Required material</span><strong>${num(s.required)} t</strong></div><div><span>Site capacity</span><strong>${num(s.capacity)} t</strong></div><div><span>Receive between</span><strong>${shortDate(s.start)} – ${shortDate(s.end)}</strong></div></div><div class="progress-label"><span>Received + incoming against target</span><strong>${num(received+incoming)} / ${num(s.required)} t</strong></div><div class="thinbar"><span style="width:${Math.min(100,(received+incoming)/s.required*100)}%"></span></div><div class="receiver-specs"><div><span>Moisture range</span><strong>${s.moistureMin}–${s.moistureMax}%</strong></div><div><span>Fines fraction</span><strong>${s.finesMin}–${s.finesMax}%</strong></div><div><span>Acceptance method</span><strong>Conditional sign-off</strong></div></div><p class="sub">${siteDrafts().length} local request draft(s). Drafts do not count as reserved or incoming material.</p>${button('Edit my site criteria','open-plan')}</section><section class="panel"><div class="section-title"><h2>Supply proposals for this site</h2><button class="text-btn" data-page="approvals">View all reviews</button></div>${siteProjects().length?siteProjects().slice(0,3).map(p=>`<article class="proposal-row"><div><strong>${esc(p.name)}</strong><p>${esc(p.material)} · ${num(p.excavated-p.retained)} t forecast</p><small>${shortDate(p.start)} – ${shortDate(p.end)} · ${p.evidence[s.id].filter(Boolean).length}/6 evidence items</small></div>${pill(p.evidence[s.id][5]?'Accepted conditionally':'Needs your review',p.evidence[s.id][5]?'':'amber')}${button('Review source','review-source','small',`data-id="${esc(p.id)}"`)}</article>`).join(''):'<div class="empty">No linked supplier proposals for this site yet.</div>'}</section></div><section class="panel mt"><div class="section-title"><h2>Receiving site activity</h2>${pill('Local records','grey')}</div>${receiverActivity()}</section>`;}
function receiverActivity(){const items=site().log||[];return items.length?items.slice(0,6).map(x=>`<div class="activity"><span class="activity-icon">✓</span><div><p>${esc(x.message)}</p><small>${esc(x.time)}</small></div></div>`).join(''):'<p class="sub">No receiving-site changes recorded yet. Supplier activity is kept with its source project.</p>';}
function siteLog(message){site().log.unshift({message,time:stamp()});}
function receivingPlan(){const s=site();return heading('RECEIVER / REQUIREMENTS','Tell suppliers what your site can accept.','These criteria belong to '+esc(s.name)+' and update route and batch checks.')+`<div class="two-col"><section class="panel"><form id="receiving-plan-form"><div class="form-grid"><label class="field">Receiving site name<input name="name" value="${esc(s.name)}" required maxlength="100"></label><label class="field">Location<input name="location" value="${esc(s.location)}" required maxlength="100"></label><label class="field">Material needed<select name="material">${['Sandy clay','Sand','Gravel','Topsoil'].map(x=>`<option ${x===s.material?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Intended use<input name="use" value="${esc(s.use)}" required maxlength="160"></label><label class="field">Required quantity (t)<input name="required" type="number" min="1" max="10000000" step="0.1" value="${s.required}" required></label><label class="field">Maximum site capacity (t)<input name="capacity" type="number" min="1" max="10000000" step="0.1" value="${s.capacity}" required></label><label class="field">Receiving starts<input name="start" type="date" value="${s.start}" required></label><label class="field">Receiving ends<input name="end" type="date" value="${s.end}" required></label></div><fieldset class="criteria-fieldset"><legend>Batch conformance envelope</legend><p class="sub">Confirm these limits with the responsible engineer and receiving site.</p><div class="form-grid"><label class="field">Minimum moisture (%)<input name="moistureMin" type="number" min="0" max="100" step="0.1" required value="${s.moistureMin}"></label><label class="field">Maximum moisture (%)<input name="moistureMax" type="number" min="0" max="100" step="0.1" required value="${s.moistureMax}"></label><label class="field">Minimum fines (%)<input name="finesMin" type="number" min="0" max="100" step="0.1" required value="${s.finesMin}"></label><label class="field">Maximum fines (%)<input name="finesMax" type="number" min="0" max="100" step="0.1" required value="${s.finesMax}"></label></div></fieldset><div class="notice">Changing these requirements reopens conditional sign-off for linked sources. Existing batch records remain unchanged; unreleased loads are checked against the new envelope.</div><div class="form-error" id="plan-error" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">Save receiving requirements</button></form></section><div class="stack"><section class="panel"><h2 style="font-size:20px;margin-top:0">Your criteria guide the workflow.</h2><div class="workflow-list"><div><b>1</b><span>Define material, quantity and window.</span></div><div><b>2</b><span>Review the source’s supporting evidence.</span></div><div><b>3</b><span>Record conditional acceptance.</span></div><div><b>4</b><span>Receive only released loads and confirm receipt.</span></div></div></section><section class="panel"><div class="section-title"><h2>Capacity used</h2></div><div class="big-number">${num(receivedMass()+transitMass())}<small> t</small></div><p class="sub">Received plus in-transit loads against ${num(s.capacity)} t site capacity.</p><div class="thinbar"><span style="width:${Math.min(100,(receivedMass()+transitMass())/s.capacity*100)}%"></span></div></section></div></div>`;}
function approvalPage(){const s=site(),ps=siteProjects();const current=ps.find(p=>p.id===state.reviewProjectId)||ps[0];if(!current)return heading('RECEIVER / SOURCE REVIEW','No proposals to review yet.','Find a source for '+esc(s.name)+'.',button('Find material','find-sources','primary'));state.reviewProjectId=current.id;const checks=current.evidence[s.id],ready=checks.slice(0,5).every(Boolean),fit=fitsProject(routes.find(r=>r.id===s.id),current);return heading('RECEIVER / SOURCE REVIEW','Accept the source against your site criteria.','Evidence is supplied by the source team. Conditional sign-off belongs to your receiving team.')+`<div class="review-selector"><label class="field">Source proposal<select id="review-project-select">${ps.map(p=>`<option value="${esc(p.id)}" ${p.id===current.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${pill('Destination: '+s.name,'clay')}</div><div class="two-col"><section class="panel"><div class="section-title"><h2>${esc(current.name)}</h2>${pill(checks[5]?'Accepted conditionally':'Pending receiver review',checks[5]?'':'amber')}</div><div class="project-stats"><div><span>Offered material</span><strong>${esc(current.material)}</strong></div><div><span>Forecast surplus</span><strong>${num(current.excavated-current.retained)} t</strong></div><div><span>Source window</span><strong>${shortDate(current.start)} – ${shortDate(current.end)}</strong></div></div><h3 class="review-heading">Supplier evidence · read only</h3>${requirements.slice(0,5).map((q,i)=>`<div class="check-row"><span class="evidence-symbol ${checks[i]?'recorded':''}">${checks[i]?'✓':'!'}</span><div class="evidence-detail"><strong>${q}</strong><small>${esc(current.files[s.id+'-'+i]||'No document reference attached')}</small></div>${pill(checks[i]?'Recorded by source':'Missing evidence',checks[i]?'':'amber')}</div>`).join('')}<div class="fit-check ${fit?'':'mismatch'}">${icon(fit?'check':'alert')}<span>${fit?'Material, whole-source volume and dates fit your current plan.':'Material, whole-source capacity or receiving dates do not match. Review the source and your site requirements.'}</span></div><div class="notice">Whole-source acceptance is assessed in this prototype. A material request draft is not a partial-volume offtake commitment. Evidence records require an accountable technical review.</div></section><div class="stack"><section class="panel"><div class="section-title"><h2>Your site criteria</h2>${icon('layers')}</div><div class="fact"><span>Material</span><strong>${s.material}</strong></div><div class="fact mt"><span>Site capacity</span><strong>${num(s.capacity)} t</strong></div><div class="fact mt"><span>Window</span><strong>${shortDate(s.start)} – ${shortDate(s.end)}</strong></div><div class="fact mt"><span>Moisture / fines</span><strong>${s.moistureMin}–${s.moistureMax}% / ${s.finesMin}–${s.finesMax}%</strong></div><button class="text-btn mt" data-page="receiving-plan">Edit site requirements</button></section><section class="panel"><h2 style="font-size:20px;margin-top:0">Receiver decision</h2><p class="sub">${checks[5]?'Conditional acceptance is recorded. You can reopen it if conditions change.':'Complete supporting evidence and a compatible source plan are required before you can sign off.'}</p>${button(checks[5]?'Reopen source acceptance':'Record conditional acceptance','receiver-signoff',checks[5]?'':'primary',`data-id="${esc(current.id)}" ${!checks[5]&&(!ready||!fit)?'disabled':''}`)}${!checks[5]&&(!ready||!fit)?`<p class="warning-text">${!ready?'Missing supplier evidence. ':''}${!fit?'Source does not fit your site plan.':''}</p>`:''}<p class="sub mt">A field PASS remains necessary for each released load.</p></section></div></div>`;}
function inboundPage(){const loads=siteBatches().filter(b=>['In transit','Delivered'].includes(b.delivery));return heading('RECEIVER / INCOMING LOADS','Know what is arriving at your site.','Confirm receipt at '+esc(site().name)+'. Source release and receipt are recorded separately.')+`<section class="metrics">${metric('In transit',num(transitMass()),'t','Source-dispatched loads for this site','truck')}${metric('Loads awaiting receipt',loads.filter(b=>b.delivery==='In transit').length,'','Your next receiving action','clock')}${metric('Received',num(receivedMass()),'t','Your site’s acknowledged mass','check')}${metric('Capacity remaining',num(Math.max(0,site().capacity-receivedMass()-transitMass())),'t','Maximum capacity − received − in transit','layers')}</section><div class="demo-inline">${icon('clock')} Manual delivery simulation · no GPS feed or carrier booking connected.</div><div class="stack mt">${loads.length?loads.reverse().map(b=>`<article class="panel"><div class="section-title"><div><div class="eyebrow">${esc(b.id)} · ${num(b.mass)} T</div><h2>${esc(b.projectName)} to ${esc(site().name)}</h2></div>${pill(b.delivery,b.delivery==='In transit'?'amber':'')}</div><div class="delivery-step"><b>Source verified</b><span class="done"></span><b>Dispatched</b><span class="${b.delivery==='Delivered'?'done':''}"></span><b>Received by you</b></div><div class="export-box"><div class="sub">Batch status: ${b.result} · ${esc(b.time)}<br>Moisture ${b.moisture}% · Fines ${b.fines}%</div>${b.delivery==='In transit'?button('Confirm receipt','receiver-receipt','primary',`data-id="${esc(b.id)}" data-project="${esc(b.projectId)}"`):pill('Receipt recorded')}</div></article>`).join(''):'<section class="panel empty">No dispatched loads for this receiving site.</section>'}</div>`;}
function receivedPage(){const batches=siteBatches().filter(b=>b.delivery==='Delivered');return heading('RECEIVER / MATERIAL RECORD','Material received, with its source trace.','Acknowledged loads at '+esc(site().name)+'.')+`<section class="panel"><div class="section-title"><h2>${num(receivedMass())} t received</h2>${pill(batches.length+' acknowledged loads','grey')}</div>${batches.length?`<div class="table-wrap"><table><caption class="screen-reader">Received material by batch and source</caption><thead><tr><th scope="col">Batch</th><th scope="col">Source</th><th scope="col">Mass</th><th scope="col">Moisture</th><th scope="col">Fines</th><th scope="col">Source QA</th></tr></thead><tbody>${batches.map(b=>`<tr><th scope="row">${esc(b.id)}</th><td>${esc(b.projectName)}</td><td>${num(b.mass)} t</td><td>${b.moisture}%</td><td>${b.fines}%</td><td>${status(b.result)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Acknowledge incoming loads to start this material record.</div>'}<p class="sub mt">Source QA records are not an independent contamination certificate. Keep the original technical evidence in your project document system.</p></section>`;}
function receiverImpact(){const received=receivedMass();return heading('RECEIVER / REPORTING','Your receiving outcome, clearly recorded.','Site-based reporting for '+esc(site().name)+'.',button(icon('download')+' Export receiving report','receiver-export','primary'))+`<section class="metrics">${metric('Reused material received',num(received),'t','Acknowledged loads at this site','leaf')}${metric('Receiving target met',num(Math.min(100,received/site().required*100)),'%','Received only; in-transit loads excluded','chart')}${metric('Incoming',num(transitMass()),'t','Forecast arrival; not yet received','truck')}${metric('Unfilled target',num(Math.max(0,site().required-received-transitMass())),'t','Target − received − incoming','layers')}</section><div class="two-col"><section class="panel"><h2 style="font-size:20px;margin-top:0">Receiving activity</h2>${receiverActivity()}</section><section class="panel"><h2 style="font-size:20px;margin-top:0">What these numbers represent</h2><p class="sub">Mass comes from source batch records and the receiving team’s receipt acknowledgement. This demo has no weighbridge integration.</p><p class="sub">Supplier haulage savings are available in the Supplier workspace. Receiver procurement savings and avoided virgin-material demand need separate evidence and are not calculated here.</p><p class="sub">Draft material requests are shown separately and never counted as confirmed material.</p></section></div>`;}
function sourceCatalog(){const siteId=site().id;return [...state.projects.map(p=>({id:'PROJECT-'+p.id,projectId:p.id,name:p.name,material:p.material,mass:Math.max(0,p.excavated-p.retained),distance:siteId==='local'?8:17,start:p.start,end:p.end,readiness:Math.round(p.evidence[siteId].filter(Boolean).length/6*100)})),...sources.filter(s=>s.id!=='SRC-01').map(s=>({...s,projectId:null}))];}
function sourceMatch(s){return (searchState.material==='Any material'||s.material===searchState.material)&&s.distance<=searchState.radius&&s.mass>=searchState.quantity&&s.start<=searchState.start&&s.end>=searchState.end;}
function sourcesPage(){const found=sourceCatalog().filter(sourceMatch),drafts=siteDrafts();return heading('RECEIVER / FIND MATERIAL','Find a source for your receiving plan.','Search from '+esc(site().name)+'. Matches are planning candidates, subject to evidence and acceptance.',button('Use my site requirements','use-site-plan'))+`<form class="filterbar" id="source-filter"><label class="field">Material<select name="material">${['Any material','Sandy clay','Sand','Gravel','Topsoil'].map(x=>`<option ${x===searchState.material?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Required quantity (t)<input name="quantity" type="number" min="1" max="10000000" value="${searchState.quantity}" required></label><label class="field">Within (km)<input name="radius" type="number" min="1" max="500" value="${searchState.radius}" required></label><label class="field">Receive from<input name="start" type="date" value="${searchState.start}" required></label><label class="field">Receive until<input name="end" type="date" value="${searchState.end}" required></label><button class="btn primary" type="submit">Find sources</button></form><div class="section-title"><h2>${found.length} planning candidate${found.length===1?'':'s'}</h2>${pill('Illustrative local sources','grey')}</div><div class="route-grid">${found.length?found.map(s=>`<article class="receiver-card"><div class="eyebrow">${s.distance} KM · ${s.projectId?'LINKED SOURCE RECORD':'DEMO CATALOGUE ONLY'}</div><h3>${esc(s.name)}</h3><div class="sub">${esc(s.material)} · ${num(s.mass)} t forecast</div><div class="route-facts"><div class="fact"><span>Availability</span><strong>${shortDate(s.start)} – ${shortDate(s.end)}</strong></div><div class="fact"><span>Evidence recorded</span><strong>${s.readiness}%</strong></div></div><div class="thinbar"><span style="width:${s.readiness}%"></span></div><p class="sub">${s.projectId?'Review this source against your selected site’s criteria.':'Evidence references are unavailable for this illustrative source. A draft request can be prepared.'}</p><div class="button-row">${s.projectId?button('Review evidence','review-source','',`data-id="${esc(s.projectId)}"`):''}${button(drafts.some(d=>d.source===s.id)?'Edit request draft':'Prepare request','request-material','primary',`data-id="${esc(s.id)}"`)}</div></article>`).join(''):`<section class="panel empty full"><h3>No sources match this search.</h3><p>Try a wider radius, a smaller quantity or another receiving window.</p>${button('Use my site requirements','use-site-plan')}</section>`}</div>${drafts.length?`<section class="panel"><div class="section-title"><h2>Request drafts for ${esc(site().name)}</h2>${pill('Not sent · not reserved','amber')}</div><div class="table-wrap"><table><thead><tr><th scope="col">Source</th><th scope="col">Requested mass</th><th scope="col">Window</th><th scope="col">Action</th></tr></thead><tbody>${drafts.map(d=>`<tr><td>${esc(sourceCatalog().find(s=>s.id===d.source)?.name||d.source)}</td><td>${num(d.quantity)} t</td><td>${shortDate(d.start)} – ${shortDate(d.end)}</td><td>${button('Edit draft','request-material','small',`data-id="${esc(d.source)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function useSiteSearch(){const s=site();searchState={material:s.material,quantity:Math.max(1,Math.round(s.required-receivedMass()-transitMass())),radius:30,start:s.start,end:s.end};}
function onboarding(){profileDialog(true);}
function profileDialog(showRoles=false){const prof=workspaceProfile();modal(modalHeader(showRoles?'Workspace setup':'Your '+state.role.toLowerCase()+' organisation','Details are saved separately for the supply and receiving teams.')+`${showRoles?`<div class="setup-role-summary"><b>Current role: ${state.role}</b><span>${receiver()?'Receiving requirements, source acceptance and incoming loads.':'Surplus forecasts, destination planning and source release.'}</span></div>`:''}<form id="v2-profile-form"><label class="field">Organisation name<input name="org" value="${esc(prof.org)}" required maxlength="70"></label><label class="field">Organisation type<select name="type">${(receiver()?['Receiving site / infrastructure project','Landscaper / material processor','Council receiving site']:['Civil / earthworks contractor','Developer','Council / infrastructure project team']).map(t=>`<option ${t===prof.type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Responsible team / contact role<input name="contact" value="${esc(prof.contact)}" required maxlength="100"></label><div class="modal-actions">${button('Cancel','close')}<button class="btn primary" type="submit">Save ${state.role.toLowerCase()} details</button></div></form>`);}
function requestDialog(id){const s=sourceCatalog().find(x=>x.id===id);if(!s){toast('This source is no longer available in the current catalogue.');return;}const existing=siteDrafts().find(x=>x.source===id);modal(modalHeader(existing?'Edit your material request':'Prepare a material request',esc(s.name)+' → '+esc(site().name))+`<form id="v2-request-form" data-source="${esc(id)}"><div class="form-grid"><label class="field">Requested mass (t)<input name="quantity" type="number" min="1" max="${Math.min(s.mass,site().capacity)}" step="0.1" value="${existing?.quantity||Math.min(searchState.quantity,s.mass,site().capacity)}" required></label><label class="field">Intended use<input name="use" value="${esc(existing?.use||site().use)}" required maxlength="160"></label><label class="field">Receive from<input name="start" type="date" value="${existing?.start||searchState.start}" required></label><label class="field">Receive until<input name="end" type="date" value="${existing?.end||searchState.end}" required></label></div><label class="field">Site conditions<textarea name="conditions" required maxlength="1000">${esc(existing?.conditions||`Material: ${site().material}; moisture ${site().moistureMin}–${site().moistureMax}%; fines ${site().finesMin}–${site().finesMax}%. Subject to supporting evidence and receiver acceptance.`)}</textarea></label><div class="notice">This saves a local draft only. No material is reserved and no supplier is contacted.</div><div id="request-error" class="form-error" role="alert" tabindex="-1"></div><div class="modal-actions">${button('Cancel','close')}<button class="btn primary" type="submit">Save request draft</button></div></form>`);}
function receiptDialog(pId,bId){const p=state.projects.find(p=>p.id===pId),b=p?.batches.find(b=>b.id===bId);if(!b||b.route!==site().id||b.delivery!=='In transit')return;const currentFit=conformsCurrent(b,routes.find(r=>r.id===site().id))&&p.material===site().material;modal(modalHeader('Confirm receipt at '+esc(site().name),esc(b.id)+' from '+esc(p.name))+`<form id="receipt-form" data-project="${esc(pId)}" data-batch="${esc(bId)}">${!currentFit?'<div class="notice">This load does not match the site’s current material or batch envelope. Keep receipt pending and reconcile changed conditions with the source team.</div>':''}<p class="sub">Source-dispatched mass: <strong>${num(b.mass)} t</strong>. Confirm receipt against your site record.</p><label class="field">Received mass (t)<input name="mass" type="number" min="0.1" max="40" step="0.1" value="${b.mass}" required><small>Mass discrepancies stay pending for review in this prototype.</small></label><label class="field">Receiving record / note<input name="reference" placeholder="e.g. gate record or weighbridge ticket" required maxlength="160"></label><div id="receipt-error" class="form-error" role="alert" tabindex="-1"></div><div class="modal-actions">${button('Cancel','close')}<button class="btn primary" type="submit" ${!currentFit?'disabled':''}>Record receipt</button></div></form>`);}
function inlineError(id,message,field){const box=$('#'+id);if(box){box.textContent=message;box.focus();}else toast(message);if(field){field.setAttribute('aria-invalid','true');if(box)field.setAttribute('aria-describedby',id);}}
function exportReceiving(){const rows=[['ReGround V2 receiving report · local demo'],['Site',site().name],['Organisation',workspaceProfile().org],['Target t',site().required],['Capacity t',site().capacity],['Received t',receivedMass()],['In transit t',transitMass()],['Exported NZ',stamp()],[],['Batch','Source','Mass t','QA','Delivery','Receipt reference']];siteBatches().forEach(b=>rows.push([b.id,b.projectName,b.mass,b.result,b.delivery,b.receiptReference||'Illustrative / not recorded']));downloadCSV(rows,'ReGround-V2-'+site().id+'-receiving.csv');}
function downloadCSV(rows,name){const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Receiving report exported with demo context.');}
function closeNavigation(){navOpen=false;render();$('.mobile-menu')?.focus();}
// Capture role-specific actions before the V1 shared handlers.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;const handled=['set-role','profile-edit','onboarding','close-nav','menu','open-plan','open-approvals','open-inbound','review-source','receiver-signoff','receiver-receipt','receiver-export','request-material','use-site-plan'];if(!handled.includes(action))return;e.stopImmediatePropagation();switch(action){case'set-role':if(id!==state.role)switchWorkspace(id);break;case'profile-edit':profileDialog();break;case'onboarding':onboarding();break;case'menu':navOpen=!navOpen;render();break;case'close-nav':closeNavigation();break;case'open-plan':navigate('receiving-plan');break;case'open-approvals':navigate('approvals');break;case'open-inbound':navigate('inbound');break;case'review-source':state.reviewProjectId=id;navigate('approvals');break;case'use-site-plan':useSiteSearch();render();toast('Search updated from your receiving site requirements.');break;case'request-material':if(receiver())requestDialog(id);break;case'receiver-signoff':{if(!receiver())return;const p=state.projects.find(p=>p.id===id),checks=p.evidence[site().id];if(checks[5]){checks[5]=false;siteLog('Source acceptance reopened: '+p.name);}else{if(!checks.slice(0,5).every(Boolean)||!fitsProject(routes.find(r=>r.id===site().id),p)){toast('Sign-off blocked: supporting evidence or site compatibility needs review.');return;}checks[5]=true;siteLog('Conditional acceptance recorded: '+p.name);}p.log.unshift({message:'Receiver '+site().name+': acceptance '+(checks[5]?'recorded':'reopened'),time:stamp()});persist();render();document.querySelector('[data-action=receiver-signoff]')?.focus();toast(checks[5]?'Conditional acceptance recorded. Field PASS still required.':'Source acceptance reopened. Unreleased loads are blocked.');break;}case'receiver-receipt':if(receiver())receiptDialog(b.dataset.project,id);break;case'receiver-export':exportReceiving();break;}},true);
document.addEventListener('change',e=>{if(e.target.id==='site-select'){e.stopImmediatePropagation();state.siteId=e.target.value;state.org=workspaceProfile().org;state.reviewProjectId=null;useSiteSearch();persist();render();$('#site-select').focus();toast('Receiving site changed. All totals now reflect '+site().name+'.');}if(e.target.id==='review-project-select'){e.stopImmediatePropagation();state.reviewProjectId=e.target.value;persist();render();$('#review-project-select').focus();}if(e.target.matches('[data-evidence]')){e.stopImmediatePropagation();if(receiver())return;const i=+e.target.dataset.evidence,p=project();if(i===5)return;p.evidence[routeFocus][i]=e.target.checked;if(!e.target.checked)p.evidence[routeFocus][5]=false;log(requirements[i]+': '+(e.target.checked?'recorded':'reopened')+' · '+routes.find(r=>r.id===routeFocus).name);const focusId=e.target.id;persist();render();$('#'+focusId)?.focus();}},true);
document.addEventListener('submit',e=>{const f=e.target,id=f.getAttribute('id'),d=Object.fromEntries(new FormData(f));if(!['v2-profile-form','receiving-plan-form','v2-request-form','receipt-form'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();if(id==='v2-profile-form'){if(!d.org.trim()||!d.contact.trim()){toast('Enter the organisation and responsible team.');return;}if(receiver())site().profile={org:d.org.trim(),type:d.type,contact:d.contact.trim()};else state.profiles.Supplier={org:d.org.trim(),type:d.type,contact:d.contact.trim()};state.org=d.org.trim();navOpen=false;persist();$('#dialog').close();render();toast(state.role+' organisation details saved.');}if(id==='receiving-plan-form'){if(!receiver())return;if(d.end<d.start){inlineError('plan-error','Receiving end must be on or after the start date.',f.elements.end);return;}if(+d.required>+d.capacity){inlineError('plan-error','Required quantity cannot exceed maximum site capacity.',f.elements.required);return;}if(+d.capacity<receivedMass()+transitMass()){inlineError('plan-error','Capacity cannot be below material already received or in transit.',f.elements.capacity);return;}if(+d.moistureMin>+d.moistureMax||+d.finesMin>+d.finesMax){inlineError('plan-error','Each minimum must be less than or equal to its maximum.');return;}if(!d.name.trim()||!d.location.trim()||!d.use.trim()){inlineError('plan-error','Enter the site name, location and intended use.');return;}const keys=['material','capacity','start','end','moistureMin','moistureMax','finesMin','finesMax'],changed=keys.some(k=>String(site()[k])!==String(d[k]));Object.assign(site(),{name:d.name.trim(),location:d.location.trim(),use:d.use.trim(),material:d.material,start:d.start,end:d.end,...Object.fromEntries(['required','capacity','moistureMin','moistureMax','finesMin','finesMax'].map(k=>[k,+d[k]]))});if(changed)state.projects.forEach(p=>{p.evidence[site().id][5]=false;});siteLog('Receiving requirements updated'+(changed?'; source sign-off reopened':''));syncRoutes();persist();render();toast('Site requirements saved'+(changed?'. Linked source acceptance needs review.':'.'));}if(id==='v2-request-form'){const s=sourceCatalog().find(s=>s.id===f.dataset.source);if(!s||d.end<d.start||d.start<s.start||d.end>s.end||d.start<site().start||d.end>site().end){inlineError('request-error','Choose dates within both source availability and your site receiving window.');return;}if(d.use.trim()===''||d.conditions.trim()===''){inlineError('request-error','Enter the intended use and acceptance conditions.');return;}state.requests=state.requests.filter(x=>!(x.source===s.id&&x.siteId===site().id));state.requests.push({source:s.id,siteId:site().id,quantity:+d.quantity,use:d.use.trim(),start:d.start,end:d.end,conditions:d.conditions.trim()});siteLog('Local material request draft saved: '+s.name);persist();$('#dialog').close();render();toast('Draft saved for '+site().name+'. It has not been sent or reserved.');}if(id==='receipt-form'){if(!receiver())return;const p=state.projects.find(p=>p.id===f.dataset.project),b=p?.batches.find(b=>b.id===f.dataset.batch);if(!b||b.delivery!=='In transit'||b.route!==site().id)return;if(!conformsCurrent(b,routes.find(r=>r.id===site().id))||p.material!==site().material){inlineError('receipt-error','This load needs review against the current receiving criteria.');return;}if(Math.abs(+d.mass-b.mass)>.001){inlineError('receipt-error','Received mass differs from the source record. Leave this load pending and reconcile the discrepancy.',f.elements.mass);return;}if(!d.reference.trim()){inlineError('receipt-error','Add a receiving record or note.',f.elements.reference);return;}b.delivery='Delivered';b.time=stamp();b.receiptReference=d.reference.trim();siteLog(b.id+' received from '+p.name+' · '+num(b.mass)+' t');p.log.unshift({message:b.id+' receipt acknowledged at '+site().name,time:stamp()});persist();$('#dialog').close();render();toast('Receipt recorded. Only this site’s receiving totals were updated.');}},true);
document.addEventListener('keydown',e=>{if($('#dialog').open)return;if(e.key==='Escape'&&navOpen){e.preventDefault();closeNavigation();return;}if(e.key==='Tab'&&navOpen){const targets=[...document.querySelectorAll('.sidebar button')].filter(x=>!x.disabled),first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('input',e=>{e.target.removeAttribute('aria-invalid');});
$('#dialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();else $('#main')?.focus({preventScroll:true});});
const baseModal=modal;modal=function(content){returnFocus=document.activeElement;baseModal(content);const h=$('#dialog h2');if(h){h.id='dialog-heading';$('#dialog').setAttribute('aria-labelledby','dialog-heading');}};
state.org=workspaceProfile().org;useSiteSearch();page=state.lastPages[state.role]||'dashboard';routeFocus=receiver()?site().id:project().route;syncRoutes();persist();render();
